package vn.iotstar.example1.config; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain filter(HttpSecurity http)throws Exception{http.authorizeHttpRequests(a->a.requestMatchers("/login","/register","/forgot-password","/css/**","/images/**").permitAll().anyRequest().authenticated()).formLogin(f->f.loginPage("/login").loginProcessingUrl("/login").usernameParameter("email").passwordParameter("password").defaultSuccessUrl("/",true).failureUrl("/login?error=true").permitAll()).logout(l->l.logoutSuccessUrl("/login?logout=true").permitAll()); return http.build();}}
